// Writes src/lib/chain/realm-source.ts: the production files of the rooms and
// board realms, which the /launch page deploys from the owner's own wallet.
// Tests stay out, as in scripts/gno/deploy.sh. A unit test fails when the
// generated file no longer matches the realms, so run this after changing them:
//
//   node scripts/embed-realms.mjs
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const realms = resolve(here, "../../../gno/realms/tradewindow");
const out = resolve(here, "../src/lib/chain/realm-source.ts");

/** The files deploy.sh sends: every .gno file but tests, and gnomod.toml. */
export function realmFiles(dir) {
  return readdirSync(dir)
    .filter((f) => (f.endsWith(".gno") && !f.endsWith("_test.gno") && !f.endsWith("_filetest.gno")) || f === "gnomod.toml")
    .sort()
    .map((name) => ({ name, body: readFileSync(join(dir, name), "utf8") }));
}

const files = { rooms: realmFiles(join(realms, "rooms")), board: realmFiles(join(realms, "board")) };
writeFileSync(
  out,
  `// Generated by scripts/embed-realms.mjs from gno/realms/tradewindow. Do not edit:
// run the script after changing a realm; a test checks the two still match.

export interface RealmFile {
  name: string;
  body: string;
}

export type RealmName = "rooms" | "board";

export const REALM_DIRS: Record<RealmName, string> = {
  rooms: "gno/realms/tradewindow/rooms",
  board: "gno/realms/tradewindow/board",
};

export const REALM_FILES: Record<RealmName, RealmFile[]> = ${JSON.stringify(files, null, 2)};
`,
);
console.log(`${out}: rooms ${files.rooms.length} files, board ${files.board.length} files`);
